import re, zlib, hashlib, struct, bisect
PDF='/home/nick/work/andesim/AndesCore_AX45MPV_DS220_V1.4.pdf'
data=open(PDF,'rb').read()
exp=[0]*512; log=[0]*256; x=1
for i in range(255):
    exp[i]=x; log[x]=i
    x ^= ((x<<1) ^ (0x11b if x&0x80 else 0)) & 0x1ff; x&=0xff
for i in range(255,512): exp[i]=exp[i-255]
def ginv(a): return 0 if a==0 else exp[255-log[a]]
def aff(b):
    r=0
    for i in range(8):
        bit=((b>>i)&1)^((b>>((i+4)%8))&1)^((b>>((i+5)%8))&1)^((b>>((i+6)%8))&1)^((b>>((i+7)%8))&1)^((0x63>>i)&1)
        r|=bit<<i
    return r
Sbox=[aff(ginv(a)) for a in range(256)]
InvS=[0]*256
for i,v in enumerate(Sbox): InvS[v]=i
def gm(a,b):
    if a==0 or b==0: return 0
    return exp[log[a]+log[b]]
T9=[gm(9,i) for i in range(256)]; T11=[gm(11,i) for i in range(256)]
T13=[gm(13,i) for i in range(256)]; T14=[gm(14,i) for i in range(256)]
INVSHIFT=[ (i%4) + 4*(((i>>2) - (i%4))%4) for i in range(16)]
Rcon=[1,2,4,8,16,32,64,128,0x1b,0x36]
def expand(key):
    w=[list(key[4*i:4*i+4]) for i in range(4)]
    for i in range(4,44):
        t=list(w[i-1])
        if i%4==0:
            t=t[1:]+t[:1]; t=[Sbox[b] for b in t]; t[0]^=Rcon[i//4-1]
        w.append([w[i-4][j]^t[j] for j in range(4)])
    return [bytes(bytearray(w[4*r+c][rr] for c in range(4) for rr in range(4))) for r in range(11)]
def dec_block(blk,rks):
    s=[blk[i]^rks[10][i] for i in range(16)]
    for rnd in range(9,0,-1):
        s=[s[INVSHIFT[i]] for i in range(16)]
        s=[InvS[b] for b in s]
        rk=rks[rnd]; s=[s[i]^rk[i] for i in range(16)]
        ns=[0]*16
        for c in (0,4,8,12):
            a0,a1,a2,a3=s[c],s[c+1],s[c+2],s[c+3]
            ns[c]  =T14[a0]^T11[a1]^T13[a2]^T9[a3]
            ns[c+1]=T9[a0]^T14[a1]^T11[a2]^T13[a3]
            ns[c+2]=T13[a0]^T9[a1]^T14[a2]^T11[a3]
            ns[c+3]=T11[a0]^T13[a1]^T9[a2]^T14[a3]
        s=ns
    s=[s[INVSHIFT[i]] for i in range(16)]
    s=[InvS[b] for b in s]
    return bytes(s[i]^rks[0][i] for i in range(16))
def cbc_dec(ct,key):
    rks=expand(key)
    body=ct[16:16+((len(ct)-16)//16)*16]
    out=bytearray(); prev=ct[:16]
    for o in range(0,len(body),16):
        blk=body[o:o+16]
        out+=bytes(a^b for a,b in zip(dec_block(blk,rks),prev)); prev=blk
    if out and 1<=out[-1]<=16: out=out[:-out[-1]]
    return bytes(out)
def parse_lit(b,i):
    depth=1; i+=1; out=bytearray()
    while depth:
        c=b[i]
        if c==0x5c:
            i+=1; c=b[i]
            m={0x6e:10,0x72:13,0x74:9,0x62:8,0x66:12}
            if c in m: out.append(m[c])
            elif c in (0x28,0x29,0x5c): out.append(c)
            elif 0x30<=c<=0x37:
                v=c-0x30
                for _ in range(2):
                    if 0x30<=b[i+1]<=0x37: i+=1; v=v*8+(b[i]-0x30)
                out.append(v&0xff)
            elif c==13:
                if b[i+1]==10: i+=1
            elif c==10: pass
            else: out.append(c)
        elif c==0x28: depth+=1; out.append(c)
        elif c==0x29:
            depth-=1
            if depth: out.append(c)
        else: out.append(c)
        i+=1
    return bytes(out)
ei=data.find(b'/Filter/Standard')
oo=data.find(b'/O(',ei); O=parse_lit(data,oo+2)
P=int(re.search(rb'/P\s+(-?\d+)',data[ei:ei+400]).group(1))
ID0=bytes.fromhex(re.search(rb'/ID\s*\[\s*<([0-9A-Fa-f]+)>',data).group(1).decode())
PAD=bytes([0x28,0xBF,0x4E,0x5E,0x4E,0x75,0x8A,0x41,0x64,0x00,0x4E,0x56,0xFF,0xFA,0x01,0x08,
0x2E,0x2E,0x00,0xB6,0xD0,0x68,0x3E,0x80,0x2F,0x0C,0xA9,0xFE,0x64,0x53,0x69,0x7A])
h=hashlib.md5(PAD+O+struct.pack('<i',P)+ID0).digest()
for _ in range(50): h=hashlib.md5(h[:16]).digest()
fkey=h[:16]
def objkey(num,gen):
    return hashlib.md5(fkey+struct.pack('<I',num)[:3]+struct.pack('<I',gen)[:2]+b'sAlT').digest()[:16]
objs=[(m.start(),int(m.group(1)),int(m.group(2))) for m in re.finditer(rb'(\d+)\s+(\d+)\s+obj\b',data)]
starts=[o[0] for o in objs]
texts={}
for m in re.finditer(rb'stream\r?\n',data):
    s=m.end(); e=data.find(b'endstream',s)
    if e<0: continue
    raw=data[s:e]
    if raw.endswith(b'\r\n'): raw=raw[:-2]
    elif raw[-1:] in (b'\r',b'\n'): raw=raw[:-1]
    k=bisect.bisect_right(starts,m.start())-1
    if k<0: continue
    _,num,gen=objs[k]
    try: texts[num]=zlib.decompress(cbc_dec(raw,objkey(num,gen)))
